// This console resolves only its own viewport pawn. Level.PlayerHarryActor and
// GameInfo are intentionally not required on a network client.
function HPCoopHarry GetCoopSaveLoadOwner()
{
    local HPCoopHarry H;
    if ( Viewport == None || Viewport.Actor == None ) return None;
    H = HPCoopHarry(Viewport.Actor);
    if ( H != None && !H.bDeleteMe ) return H;
    foreach Viewport.Actor.AllActors(Class'HPCoopHarry', H)
        if ( !H.bDeleteMe && H.Player == Viewport ) return H;
    return None;
}

function bool RejectCoopSaveLoad(optional string Origin)
{
    local HPCoopHarry H;
    H = GetCoopSaveLoadOwner();
    if ( H == None ) return False;
    H.ClientMessage("Save/load is unavailable in this test build");
    if ( menuBook != None && menuBook.StatusBarTextWindow != None )
        menuBook.ToolTip("Save/load is unavailable in this test build");
    Log("[MP_CHECKPOINT] blocked origin=" $ Origin $ " owner=" $ H);
    return True;
}

function bool IsSaveLoadTravelURL(string URL)
{
    local string UpperURL, MapPart;
    local int OptionAt;
    UpperURL = Caps(URL);
    if ( InStr(UpperURL, "?LOAD") >= 0 ) return True;
    OptionAt = InStr(UpperURL, "?");
    MapPart = UpperURL;
    if ( OptionAt >= 0 ) MapPart = Left(UpperURL, OptionAt);
    return Right(MapPart, 4) == ".USA";
}

